请对以下 case 进行三维加权评分。

=== case_id ===
Case-10-rainy-taxi-006

=== 用户原始指令 (query.txt) ===
整个卡片点一下能跳到打车软件 能读我日历的行程

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个卡片点一下能跳到打车软件 能读我日历的行程",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "taxi://home"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "title": {
              "type": "string",
              "description": "下一条适合打车前往的日历行程标题，使用脱敏样例。",
              "sampleValue": "机场接人"
            },
            "eventLocation": {
              "type": "string",
              "description": "行程地点短文本，使用脱敏样例。",
              "sampleValue": "T3航站楼"
            },
            "dtStart": {
              "type": "string",
              "description": "行程开始时间，如果是当天则为 HH:MM。",
              "sampleValue": "18:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "行程结束时间，如果是当天则为 HH:MM。",
              "sampleValue": "19:20"
            },
            "entityId": {
              "type": "string",
              "description": "日历行程唯一标识符，使用脱敏样例。",
              "sampleValue": "calendar_sample_001"
            }
          }
        ]
      }
    },
    "state": {
      "loading": {
        "type": "boolean",
        "description": "日历行程加载状态。",
        "sampleValue": false
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车图标，适合雨天打车场景中的出行入口识别。"
    }
  ]
}

